import { serve } from 'https://deno.land/std@0.224.0/http/server.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.98.0';
import { parseProductHtml, parseProductsHtml } from '../_shared/html_parser.ts';
import { r2Upload, r2PublicUrl } from '../_shared/r2.ts';
import {
  assertUrlResolvesPublic,
  type DnsResolver,
} from '../_shared/ssrf_validator.ts';

type JsonRecord = Record<string, unknown>;

const MAX_BODY_BYTES = 64 * 1024;
const MAX_HTML_BYTES = 2 * 1024 * 1024;
const MAX_IMAGE_BYTES = 5 * 1024 * 1024;
const MAX_REDIRECTS = 5;
const MAX_URL_LENGTH = 2_048;
const HTML_TYPES = new Set(['text/html', 'application/xhtml+xml']);
const IMAGE_TYPES = new Set(['image/jpeg', 'image/png', 'image/webp']);
const DEFAULT_ALLOWED_ORIGINS = [
  'http://localhost:3000',
  'http://127.0.0.1:3000',
  'http://localhost:5173',
  'http://127.0.0.1:5173',
];

function configuredOrigins() {
  return new Set(
    `${Deno.env.get('PRODUCT_IMPORT_ALLOWED_ORIGINS') || ''},${DEFAULT_ALLOWED_ORIGINS.join(',')}`
      .split(',')
      .map((value) => value.trim())
      .filter(Boolean),
  );
}

function corsHeaders(origin: string | null) {
  const allowed = origin && configuredOrigins().has(origin) ? origin : '';
  return {
    'access-control-allow-origin': allowed,
    'access-control-allow-headers': 'authorization, x-client-info, apikey, content-type',
    'access-control-allow-methods': 'POST, OPTIONS',
    'cache-control': 'no-store',
    'x-content-type-options': 'nosniff',
    vary: 'Origin',
  };
}

function json(status: number, body: JsonRecord, origin: string | null) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders(origin), 'content-type': 'application/json; charset=utf-8' },
  });
}

async function readJsonWithinLimit(request: Request): Promise<JsonRecord> {
  if (!request.body) throw new SyntaxError('invalid_json');
  const reader = request.body.getReader();
  const decoder = new TextDecoder();
  let size = 0;
  let text = '';
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      size += value.byteLength;
      if (size > MAX_BODY_BYTES) throw new RangeError('payload_too_large');
      text += decoder.decode(value, { stream: true });
    }
    text += decoder.decode();
    const parsed = JSON.parse(text);
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw new SyntaxError('invalid_json');
    return parsed as JsonRecord;
  } finally {
    reader.releaseLock();
  }
}

function normalizedContentType(response: Response) {
  return (response.headers.get('content-type') || '').split(';', 1)[0].trim().toLowerCase();
}

async function readLimitedBytes(response: Response, maximum: number) {
  const declared = Number(response.headers.get('content-length') || 0);
  if (declared > maximum) throw new RangeError('response_too_large');
  if (!response.body) return new Uint8Array();

  const reader = response.body.getReader();
  const chunks: Uint8Array[] = [];
  let size = 0;
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      size += value.byteLength;
      if (size > maximum) {
        await reader.cancel('response_too_large');
        throw new RangeError('response_too_large');
      }
      chunks.push(value);
    }
  } finally {
    reader.releaseLock();
  }

  const result = new Uint8Array(size);
  let offset = 0;
  for (const chunk of chunks) {
    result.set(chunk, offset);
    offset += chunk.byteLength;
  }
  return result;
}

type SafeFetchOptions = {
  accept: string;
  maximumBytes: number;
  timeoutMs?: number;
  fetcher?: typeof fetch;
  resolver?: DnsResolver;
};

export async function safeFetch(urlValue: string, options: SafeFetchOptions): Promise<Response> {
  if (typeof urlValue !== 'string' || !urlValue || urlValue.length > MAX_URL_LENGTH) {
    throw new Error('URL inválida ou não permitida');
  }

  const fetcher = options.fetcher || fetch;
  const deadline = Date.now() + (options.timeoutMs || 10_000);
  let current = await assertUrlResolvesPublic(urlValue, options.resolver);

  for (let redirectCount = 0; redirectCount <= MAX_REDIRECTS; redirectCount += 1) {
    const remaining = deadline - Date.now();
    if (remaining <= 0) throw new Error('Tempo limite excedido ao consultar URL');
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), remaining);
    let response: Response;
    try {
      response = await fetcher(current.toString(), {
        signal: controller.signal,
        redirect: 'manual',
        headers: {
          accept: options.accept,
          'user-agent': 'Mozilla/5.0 (compatible; GSA-Store-Bot/2.0)',
        },
      });
    } catch (error: any) {
      if (error?.name === 'AbortError') throw new Error('Tempo limite excedido ao consultar URL');
      throw new Error('Falha ao consultar a URL');
    } finally {
      clearTimeout(timeoutId);
    }

    if ([301, 302, 303, 307, 308].includes(response.status)) {
      if (redirectCount === MAX_REDIRECTS) {
        await response.body?.cancel();
        throw new Error('Limite de redirecionamentos excedido');
      }
      const location = response.headers.get('location');
      await response.body?.cancel();
      if (!location) throw new Error('Redirecionamento sem destino válido');
      const target = new URL(location, current);
      if (current.protocol === 'https:' && target.protocol !== 'https:') {
        throw new Error('Redirecionamento inseguro não permitido');
      }
      current = await assertUrlResolvesPublic(target.toString(), options.resolver);
      continue;
    }

    if (!response.ok) {
      await response.body?.cancel();
      throw new Error(`O destino respondeu com status ${response.status}`);
    }
    const declared = Number(response.headers.get('content-length') || 0);
    if (declared > options.maximumBytes) {
      await response.body?.cancel();
      throw new RangeError('response_too_large');
    }
    return response;
  }
  throw new Error('Limite de redirecionamentos excedido');
}

function clientIp(request: Request) {
  return request.headers.get('cf-connecting-ip')
    || request.headers.get('x-real-ip')
    || request.headers.get('x-forwarded-for')?.split(',')[0]?.trim()
    || 'unknown';
}

async function digest(value: string) {
  const hash = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(value));
  return Array.from(new Uint8Array(hash)).map((byte) => byte.toString(16).padStart(2, '0')).join('');
}

async function auditLog(client: any, actor: any, action: string, details: JsonRecord) {
  const { error } = await client.from('sistema_logs').insert({
    acao: action,
    detalhes: JSON.stringify(details),
    ator_tipo: actor.ator_tipo,
    ator_id: actor.ator_id,
    ator_nome: actor.ator_nome,
  });
  if (error) console.error(`Falha ao registrar auditoria ${action}:`, error);
}

async function requireRateLimit(client: any, key: string, maximum: number) {
  const { data, error } = await client.rpc('gsa_auth_rate_limit_check', {
    p_bucket_key: key,
    p_limit: maximum,
    p_window_seconds: 3600,
    p_block_seconds: 3600,
  });
  if (error || typeof data?.allowed !== 'boolean') throw new Error('rate_limit_unavailable');
  return data as { allowed: boolean; retry_after?: number };
}

async function fetchHtml(url: string) {
  const response = await safeFetch(url, {
    accept: 'text/html,application/xhtml+xml',
    maximumBytes: MAX_HTML_BYTES,
  });
  if (!HTML_TYPES.has(normalizedContentType(response))) {
    await response.body?.cancel();
    throw new TypeError('A URL não retornou conteúdo HTML válido');
  }
  const bytes = await readLimitedBytes(response, MAX_HTML_BYTES);
  return {
    html: new TextDecoder('utf-8', { fatal: false }).decode(bytes),
    finalUrl: response.url || url,
  };
}

async function fetchImage(url: string) {
  const response = await safeFetch(url, {
    accept: 'image/jpeg,image/png,image/webp',
    maximumBytes: MAX_IMAGE_BYTES,
  });
  const contentType = normalizedContentType(response);
  if (!IMAGE_TYPES.has(contentType)) {
    await response.body?.cancel();
    throw new TypeError('Tipo de imagem inválido');
  }
  const bytes = await readLimitedBytes(response, MAX_IMAGE_BYTES);
  return { blob: new Blob([bytes], { type: contentType }), contentType };
}

export async function handleRequest(request: Request) {
  const origin = request.headers.get('origin');
  if (origin && !configuredOrigins().has(origin)) return json(403, { error: 'origin_not_allowed' }, origin);
  if (request.method === 'OPTIONS') return new Response(null, { status: 204, headers: corsHeaders(origin) });
  if (request.method !== 'POST') return json(405, { error: 'method_not_allowed' }, origin);
  if (!(request.headers.get('content-type') || '').toLowerCase().includes('application/json')) {
    return json(415, { error: 'unsupported_media_type' }, origin);
  }
  const declaredLength = Number(request.headers.get('content-length') || 0);
  if (declaredLength > MAX_BODY_BYTES) return json(413, { error: 'payload_too_large' }, origin);

  let body: JsonRecord;
  try {
    body = await readJsonWithinLimit(request);
  } catch (error) {
    return json(
      error instanceof RangeError ? 413 : 400,
      { error: error instanceof RangeError ? 'payload_too_large' : 'invalid_json' },
      origin,
    );
  }

  const supabaseUrl = Deno.env.get('SUPABASE_URL');
  const serviceRoleKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');
  if (!supabaseUrl || !serviceRoleKey) return json(503, { error: 'server_not_configured' }, origin);
  const client = createClient(supabaseUrl, serviceRoleKey, {
    auth: { persistSession: false, autoRefreshToken: false },
  }) as any;

  const sessaoId = String(body.sessaoId || '');
  const sessionToken = String(body.sessionToken || '');
  if (!sessaoId || sessaoId.length > 64 || !sessionToken || sessionToken.length > 256) {
    return json(401, { error: 'session_required' }, origin);
  }

  const { data: actor, error: authError } = await client.rpc(
    'gsa_admin_authorize_product_url_import',
    { p_sessao_id: sessaoId, p_session_token: sessionToken },
  );
  if (authError || !actor?.ator_id) {
    return json(403, { error: 'session_or_module_not_allowed' }, origin);
  }

  const action = String(body.action || '');
  const actorHash = await digest(`${serviceRoleKey}:actor:${actor.ator_tipo}:${actor.ator_id}`);
  const ipHash = await digest(`${serviceRoleKey}:ip:${clientIp(request)}`);
  try {
    const [actorLimit, ipLimit] = await Promise.all([
      requireRateLimit(client, `product-url-import:${action}:actor:${actorHash}`, 120),
      requireRateLimit(client, `product-url-import:${action}:ip:${ipHash}`, 180),
    ]);
    const blocked = !actorLimit.allowed || !ipLimit.allowed;
    if (blocked) {
      const retryAfter = Math.max(
        1,
        Number(actorLimit.retry_after || 0),
        Number(ipLimit.retry_after || 0),
      );
      return json(429, { error: 'too_many_attempts', retry_after: retryAfter }, origin);
    }
  } catch (error) {
    console.error('Limitador da importação por URL indisponível:', error);
    return json(503, { error: 'rate_limit_unavailable' }, origin);
  }

  try {
    if (action === 'analyze' || action === 'discover_products') {
      const sourceUrl = String(body.url || '');
      const { html, finalUrl } = await fetchHtml(sourceUrl);
      if (action === 'analyze') {
        const parsed = parseProductHtml(html, finalUrl);
        await auditLog(client, actor, 'IMPORTAR_DADOS_PRODUTO_URL', {
          url_consultada: new URL(sourceUrl).hostname,
          campos_encontrados: Object.keys(parsed.origem_campos),
          status: 'sucesso',
        });
        return json(200, {
          success: true,
          data: { ...parsed, url_original: sourceUrl, url_final: finalUrl, avisos: [] },
        }, origin);
      }

      const candidates = parseProductsHtml(html, finalUrl).slice(0, 500);
      await auditLog(client, actor, 'DESCOBRIR_PRODUTOS_PAGINA', {
        url_consultada: new URL(sourceUrl).hostname,
        encontrados: candidates.length,
        status: 'sucesso',
      });
      return json(200, {
        success: true,
        data: { candidates, total: candidates.length },
      }, origin);
    }

    if (action === 'analyze_products') {
      const urls = body.urls;
      if (!Array.isArray(urls) || urls.length === 0 || urls.length > 10) {
        return json(400, { error: 'invalid_url_batch' }, origin);
      }
      const results = await Promise.all(urls.map(async (value) => {
        const sourceUrl = typeof value === 'string' ? value : '';
        try {
          const { html, finalUrl } = await fetchHtml(sourceUrl);
          const parsed = parseProductHtml(html, finalUrl);
          return { url: sourceUrl, success: true, data: { ...parsed, url_final: finalUrl } };
        } catch (error: any) {
          return { url: sourceUrl, error: error?.message || 'Falha ao analisar URL' };
        }
      }));
      await auditLog(client, actor, 'ANALISAR_PRODUTOS_EM_LOTE', {
        quantidade: urls.length,
        status: 'concluido',
      });
      return json(200, { success: true, data: results }, origin);
    }

    if (action === 'copy_images') {
      const images = body.images;
      if (!Array.isArray(images) || images.length === 0 || images.length > 10) {
        return json(400, { error: 'invalid_image_batch' }, origin);
      }
      const uploaded: string[] = [];
      const failed: string[] = [];
      for (const value of images) {
        const imageUrl = typeof value === 'string' ? value : '';
        try {
          const { blob, contentType } = await fetchImage(imageUrl);
          const extension = contentType === 'image/jpeg' ? 'jpg' : contentType.split('/')[1];
          const fileName = `imports/produtos/${crypto.randomUUID()}.${extension}`;
          const fileBytes = new Uint8Array(await blob.arrayBuffer());
          const r2Key = 'public/store-images/' + fileName;
          await r2Upload(r2Key, fileBytes, contentType);
          uploaded.push(r2PublicUrl(r2Key));
        } catch {
          failed.push(imageUrl);
        }
      }
      await auditLog(client, actor, 'IMPORTAR_DADOS_PRODUTO_URL', {
        imagens_copiadas: uploaded.length,
        imagens_falhas: failed.length,
        status: 'copia_imagens',
      });
      return json(200, { success: true, data: { uploaded, failed } }, origin);
    }

    if (action === 'copy_product_images') {
      const batchId = String(body.batchId || '');
      const products = body.products;
      if (
        !/^[0-9a-f]{8}-[0-9a-f-]{27}$/i.test(batchId)
        || !Array.isArray(products)
        || products.length === 0
        || products.length > 10
      ) {
        return json(400, { error: 'invalid_product_batch' }, origin);
      }

      const results: JsonRecord[] = [];
      for (const value of products) {
        const product = value && typeof value === 'object' ? value as JsonRecord : {};
        const clientId = String(product.client_id || '');
        const images = Array.isArray(product.images) ? product.images.slice(0, 5) : [];
        const uploaded: string[] = [];
        const failed: string[] = [];
        if (!/^[a-zA-Z0-9_-]{1,80}$/.test(clientId)) {
          results.push({ client_id: clientId, uploaded, failed: images.map(String) });
          continue;
        }
        for (const value of images) {
          const imageUrl = typeof value === 'string' ? value : '';
          try {
            const { blob, contentType } = await fetchImage(imageUrl);
            const extension = contentType === 'image/jpeg' ? 'jpg' : contentType.split('/')[1];
            const fileName = `imports/produtos/${batchId}/${clientId}/${crypto.randomUUID()}.${extension}`;
            const fileBytes = new Uint8Array(await blob.arrayBuffer());
            const r2Key = 'public/store-images/' + fileName;
            await r2Upload(r2Key, fileBytes, contentType);
            uploaded.push(r2PublicUrl(r2Key));
          } catch {
            failed.push(imageUrl);
          }
        }
        results.push({ client_id: clientId, uploaded, failed });
      }
      await auditLog(client, actor, 'COPIAR_IMAGENS_LOTE', {
        batch_id: batchId,
        produtos_processados: products.length,
      });
      return json(200, { success: true, data: results }, origin);
    }

    return json(400, { error: 'invalid_action' }, origin);
  } catch (error: any) {
    console.error('Falha na importação por URL:', error);
    const status = error instanceof RangeError
      ? 413
      : error instanceof TypeError
        ? 415
        : 400;
    return json(status, { error: error?.message || 'import_failed' }, origin);
  }
}

if (import.meta.main) serve(handleRequest);

// @ts-nocheck
import { DOMParser } from "https://deno.land/x/deno_dom/deno-dom-wasm.ts";

export interface ParsedProduct {
  candidate_id?: string;
  nome: string | null;
  descricao: string | null;
  preco: number | null;
  moeda: string | null;
  nome_fornecedor: string | null;
  imagens: string[];
  origem_campos: Record<string, string>;
}

export function parseProductHtml(html: string, originalUrl: string): ParsedProduct {
  const doc = new DOMParser().parseFromString(html, "text/html");
  if (!doc) {
    throw new Error("Failed to parse HTML");
  }

  const result: ParsedProduct = {
    nome: null,
    descricao: null,
    preco: null,
    moeda: null,
    nome_fornecedor: null,
    imagens: [],
    origem_campos: {}
  };

  const getAbsoluteUrl = (relUrl: string) => {
    try {
      return new URL(relUrl, originalUrl).href;
    } catch {
      return relUrl;
    }
  };

  // 1. JSON-LD
  const jsonLdScripts = doc.querySelectorAll('script[type="application/ld+json"]');
  for (const script of jsonLdScripts) {
    try {
      const content = script.textContent;
      if (!content) continue;
      let data = JSON.parse(content);

      const processJsonLd = (obj: any) => {
        if (!obj) return;
        if (Array.isArray(obj)) {
          obj.forEach(processJsonLd);
          return;
        }
        if (obj['@graph'] && Array.isArray(obj['@graph'])) {
          obj['@graph'].forEach(processJsonLd);
          return;
        }

        if (obj['@type'] === 'Product') {
          if (!result.nome && obj.name) {
            result.nome = typeof obj.name === 'string' ? obj.name : obj.name[0];
            result.origem_campos['nome'] = 'json_ld';
          }
          if (!result.descricao && obj.description) {
            result.descricao = typeof obj.description === 'string' ? obj.description : obj.description[0];
            result.origem_campos['descricao'] = 'json_ld';
          }
          if (obj.image) {
            const imgs = Array.isArray(obj.image) ? obj.image : [obj.image];
            imgs.forEach((img: any) => {
              if (typeof img === 'string') {
                if (!result.imagens.includes(getAbsoluteUrl(img))) {
                  result.imagens.push(getAbsoluteUrl(img));
                }
              } else if (img && img.url) {
                if (!result.imagens.includes(getAbsoluteUrl(img.url))) {
                  result.imagens.push(getAbsoluteUrl(img.url));
                }
              }
            });
            if (result.imagens.length > 0 && !result.origem_campos['imagens']) {
              result.origem_campos['imagens'] = 'json_ld';
            }
          }

          if (obj.brand && obj.brand.name && !result.nome_fornecedor) {
            result.nome_fornecedor = typeof obj.brand.name === 'string' ? obj.brand.name : null;
            if (result.nome_fornecedor) result.origem_campos['nome_fornecedor'] = 'json_ld';
          }

          const offers = obj.offers;
          if (offers && !result.preco) {
            const offerList = Array.isArray(offers) ? offers : [offers];
            for (const offer of offerList) {
              const price = offer.price || offer.lowPrice;
              if (price !== undefined && price !== null) {
                const numPrice = parseFloat(String(price).replace(/[^0-9.]/g, ''));
                if (!isNaN(numPrice) && numPrice > 0) {
                  result.preco = numPrice;
                  result.moeda = offer.priceCurrency || 'BRL';
                  result.origem_campos['preco'] = 'json_ld';
                  result.origem_campos['moeda'] = 'json_ld';
                  break;
                }
              }
            }
          }
        }
      };

      processJsonLd(data);
    } catch (e) {
      // ignore JSON parse errors
    }
  }

  // 2. Open Graph
  if (!result.nome) {
    const ogTitle = doc.querySelector('meta[property="og:title"]');
    if (ogTitle) {
      result.nome = ogTitle.getAttribute('content');
      result.origem_campos['nome'] = 'open_graph';
    }
  }

  if (!result.descricao) {
    const ogDesc = doc.querySelector('meta[property="og:description"]');
    if (ogDesc) {
      result.descricao = ogDesc.getAttribute('content');
      result.origem_campos['descricao'] = 'open_graph';
    }
  }

  if (result.imagens.length === 0) {
    const ogImage = doc.querySelector('meta[property="og:image"]');
    if (ogImage && ogImage.getAttribute('content')) {
      result.imagens.push(getAbsoluteUrl(ogImage.getAttribute('content')!));
      result.origem_campos['imagens'] = 'open_graph';
    }
  }

  if (!result.preco) {
    const ogPrice = doc.querySelector('meta[property="product:price:amount"]');
    const ogCurrency = doc.querySelector('meta[property="product:price:currency"]');
    if (ogPrice && ogPrice.getAttribute('content')) {
      const p = parseFloat(ogPrice.getAttribute('content')!.replace(/[^0-9.]/g, ''));
      if (!isNaN(p) && p > 0) {
        result.preco = p;
        result.origem_campos['preco'] = 'open_graph';
        if (ogCurrency && ogCurrency.getAttribute('content')) {
          result.moeda = ogCurrency.getAttribute('content');
          result.origem_campos['moeda'] = 'open_graph';
        } else {
          result.moeda = 'BRL';
        }
      }
    }
  }

  // 3. Meta / Itemprop fallback
  if (!result.nome) {
    const metaTitle = doc.querySelector('title');
    if (metaTitle && metaTitle.textContent) {
      result.nome = metaTitle.textContent;
      result.origem_campos['nome'] = 'title';
    }
  }

  if (!result.descricao) {
    const metaDesc = doc.querySelector('meta[name="description"]');
    if (metaDesc) {
      result.descricao = metaDesc.getAttribute('content');
      result.origem_campos['descricao'] = 'meta';
    }
  }

  if (!result.nome_fornecedor) {
    const ogSiteName = doc.querySelector('meta[property="og:site_name"]');
    if (ogSiteName) {
      result.nome_fornecedor = ogSiteName.getAttribute('content');
      result.origem_campos['nome_fornecedor'] = 'open_graph';
    } else {
       try {
         result.nome_fornecedor = new URL(originalUrl).hostname.replace('www.', '');
         result.origem_campos['nome_fornecedor'] = 'url';
       } catch {}
    }
  }

  // Normalize and decode HTML entities
  const decodeHtmlEntities = (text: string) => {
    return text
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/&amp;/g, '&')
      .replace(/&quot;/g, '"')
      .replace(/&#39;/g, "'")
      .replace(/&#x27;/g, "'")
      .replace(/&nbsp;/g, ' ');
  };

  if (result.descricao) {
    let decoded = decodeHtmlEntities(result.descricao);
    // Strip HTML tags if any sneaked in
    result.descricao = decoded.replace(/<[^>]*>?/gm, ' ').replace(/\s+/g, ' ').trim();
  }
  if (result.nome) {
    let decoded = decodeHtmlEntities(result.nome);
    result.nome = decoded.replace(/<[^>]*>?/gm, ' ').replace(/\s+/g, ' ').trim();
  }

  return result;
}

export function parseProductsHtml(html: string, originalUrl: string): ParsedProduct[] {
  const doc = new DOMParser().parseFromString(html, "text/html");
  if (!doc) {
    throw new Error("Failed to parse HTML");
  }

  const candidates: ParsedProduct[] = [];
  const getAbsoluteUrl = (relUrl: string) => {
    try {
      return new URL(relUrl, originalUrl).href;
    } catch {
      return relUrl;
    }
  };

  const decodeHtmlEntities = (text: string) => {
    return text
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/&amp;/g, '&')
      .replace(/&quot;/g, '"')
      .replace(/&#39;/g, "'")
      .replace(/&#x27;/g, "'")
      .replace(/&nbsp;/g, ' ');
  };

  const normalizeText = (text: string | null) => {
    if (!text) return null;
    let decoded = decodeHtmlEntities(text);
    return decoded.replace(/<[^>]*>?/gm, ' ').replace(/\s+/g, ' ').trim() || null;
  };

  let candidateCount = 0;

  const addCandidate = (p: Partial<ParsedProduct>) => {
    if (candidates.length >= 100) return; // Limit to 100 candidates
    const nome = normalizeText(p.nome || null);
    if (!nome) return; // Name is required to be a valid candidate

    // Basic deduplication during parse
    const exists = candidates.find(c => c.nome === nome);
    if (exists) return;

    candidateCount++;
    candidates.push({
      candidate_id: `cand_${Date.now()}_${candidateCount}`,
      nome: nome,
      descricao: normalizeText(p.descricao || null),
      preco: p.preco || null,
      moeda: p.moeda || 'BRL',
      nome_fornecedor: p.nome_fornecedor || null,
      imagens: Array.isArray(p.imagens) ? p.imagens : [],
      origem_campos: p.origem_campos || {}
    });
  };

  // 1. Find ItemList or multiple Product objects in JSON-LD
  const jsonLdScripts = doc.querySelectorAll('script[type="application/ld+json"]');
  for (const script of jsonLdScripts) {
    try {
      const content = script.textContent;
      if (!content) continue;
      let data = JSON.parse(content);

      const processJsonLd = (obj: any) => {
        if (!obj) return;
        if (Array.isArray(obj)) {
          obj.forEach(processJsonLd);
          return;
        }
        if (obj['@graph'] && Array.isArray(obj['@graph'])) {
          obj['@graph'].forEach(processJsonLd);
          return;
        }

        if (obj['@type'] === 'ItemList' && Array.isArray(obj.itemListElement)) {
          obj.itemListElement.forEach((item: any) => {
            if (item.item && item.item['@type'] === 'Product') {
              processJsonLd(item.item);
            } else if (item.url) {
              // We might just have a list of URLs, but we need product details
              // We can't do much with just a URL without fetching it, which we don't do here.
            }
          });
          return;
        }

        if (obj['@type'] === 'Product') {
          const p: Partial<ParsedProduct> = { origem_campos: { 'nome': 'json_ld' } };
          p.nome = typeof obj.name === 'string' ? obj.name : (obj.name?.[0] || null);
          if (obj.description) {
            p.descricao = typeof obj.description === 'string' ? obj.description : (obj.description?.[0] || null);
            p.origem_campos!['descricao'] = 'json_ld';
          }
          p.imagens = [];
          if (obj.image) {
            const imgs = Array.isArray(obj.image) ? obj.image : [obj.image];
            imgs.forEach((img: any) => {
              if (typeof img === 'string') {
                p.imagens!.push(getAbsoluteUrl(img));
              } else if (img && img.url) {
                p.imagens!.push(getAbsoluteUrl(img.url));
              }
            });
            if (p.imagens.length > 0) p.origem_campos!['imagens'] = 'json_ld';
          }

          if (obj.brand && obj.brand.name) {
            p.nome_fornecedor = typeof obj.brand.name === 'string' ? obj.brand.name : null;
            if (p.nome_fornecedor) p.origem_campos!['nome_fornecedor'] = 'json_ld';
          }

          const offers = obj.offers;
          if (offers) {
            const offerList = Array.isArray(offers) ? offers : [offers];
            for (const offer of offerList) {
              const price = offer.price || offer.lowPrice;
              if (price !== undefined && price !== null) {
                const numPrice = parseFloat(String(price).replace(/[^0-9.]/g, ''));
                if (!isNaN(numPrice) && numPrice > 0) {
                  p.preco = numPrice;
                  p.moeda = offer.priceCurrency || 'BRL';
                  p.origem_campos!['preco'] = 'json_ld';
                  p.origem_campos!['moeda'] = 'json_ld';
                  break;
                }
              }
            }
          }
          addCandidate(p);
        }
      };
      processJsonLd(data);
    } catch (e) {
      // ignore
    }
  }

  // 2. Microdata fallback (very basic)
  if (candidates.length === 0) {
    const products = doc.querySelectorAll('[itemtype*="Product"]');
    products.forEach(prod => {
      const p: Partial<ParsedProduct> = { origem_campos: { 'nome': 'microdata' }, imagens: [] };
      const nameEl = prod.querySelector('[itemprop="name"]');
      if (nameEl) p.nome = nameEl.textContent;

      const descEl = prod.querySelector('[itemprop="description"]');
      if (descEl) p.descricao = descEl.textContent;

      const priceEl = prod.querySelector('[itemprop="price"]');
      if (priceEl) {
         let content = priceEl.getAttribute('content') || priceEl.textContent;
         if (content) {
             const num = parseFloat(content.replace(/[^0-9.]/g, ''));
             if (!isNaN(num) && num > 0) p.preco = num;
         }
      }
      const imgEl = prod.querySelector('img[itemprop="image"]');
      if (imgEl && imgEl.getAttribute('src')) {
         p.imagens!.push(getAbsoluteUrl(imgEl.getAttribute('src')!));
      }

      if (p.nome) addCandidate(p);
    });
  }

  // Set provider name if missing
  let defaultProvider = null;
  const ogSiteName = doc.querySelector('meta[property="og:site_name"]');
  if (ogSiteName) {
    defaultProvider = ogSiteName.getAttribute('content');
  } else {
    try {
      defaultProvider = new URL(originalUrl).hostname.replace('www.', '');
    } catch {}
  }

  candidates.forEach(c => {
    if (!c.nome_fornecedor) {
      c.nome_fornecedor = defaultProvider;
      c.origem_campos['nome_fornecedor'] = ogSiteName ? 'open_graph' : 'url';
    }
  });

  return candidates;
}

export type DnsRecordType = 'A' | 'AAAA';
export type DnsResolver = (hostname: string, recordType: DnsRecordType) => Promise<string[]>;

const BLOCKED_HOST_SUFFIXES = [
  '.internal',
  '.local',
  '.localhost',
  '.home',
  '.lan',
  '.corp',
  '.test',
  '.invalid',
  '.example',
];

function normalizeHostname(hostname: string) {
  return hostname.toLowerCase().replace(/^\[|\]$/g, '').replace(/\.$/, '');
}

function parseIpv4(value: string): number[] | null {
  if (!/^\d{1,3}(?:\.\d{1,3}){3}$/.test(value)) return null;
  const octets = value.split('.').map(Number);
  return octets.every((octet) => Number.isInteger(octet) && octet >= 0 && octet <= 255)
    ? octets
    : null;
}

function ipv4Number(octets: number[]) {
  return (((octets[0] * 256 + octets[1]) * 256 + octets[2]) * 256) + octets[3];
}

function isPublicIpv4(value: string) {
  const octets = parseIpv4(value);
  if (!octets) return false;
  const address = ipv4Number(octets);
  const ranges = [
    ['0.0.0.0', '0.255.255.255'],
    ['10.0.0.0', '10.255.255.255'],
    ['100.64.0.0', '100.127.255.255'],
    ['127.0.0.0', '127.255.255.255'],
    ['169.254.0.0', '169.254.255.255'],
    ['172.16.0.0', '172.31.255.255'],
    ['192.0.0.0', '192.0.0.255'],
    ['192.0.2.0', '192.0.2.255'],
    ['192.88.99.0', '192.88.99.255'],
    ['192.168.0.0', '192.168.255.255'],
    ['198.18.0.0', '198.19.255.255'],
    ['198.51.100.0', '198.51.100.255'],
    ['203.0.113.0', '203.0.113.255'],
    ['224.0.0.0', '255.255.255.255'],
  ] as const;
  return !ranges.some(([start, end]) => {
    const lower = ipv4Number(parseIpv4(start)!);
    const upper = ipv4Number(parseIpv4(end)!);
    return address >= lower && address <= upper;
  });
}

function parseIpv6(value: string): number[] | null {
  let normalized = normalizeHostname(value);
  if (!normalized.includes(':') || normalized.includes('%')) return null;

  const ipv4Match = normalized.match(/(\d{1,3}(?:\.\d{1,3}){3})$/);
  if (ipv4Match) {
    const ipv4 = parseIpv4(ipv4Match[1]);
    if (!ipv4) return null;
    normalized = normalized.slice(0, -ipv4Match[1].length)
      + ((ipv4[0] << 8) | ipv4[1]).toString(16)
      + ':'
      + ((ipv4[2] << 8) | ipv4[3]).toString(16);
  }

  if ((normalized.match(/::/g) || []).length > 1) return null;
  const [leftRaw, rightRaw = ''] = normalized.split('::');
  const left = leftRaw ? leftRaw.split(':') : [];
  const right = rightRaw ? rightRaw.split(':') : [];
  if ([...left, ...right].some((part) => !/^[0-9a-f]{1,4}$/i.test(part))) return null;

  const missing = 8 - left.length - right.length;
  if ((normalized.includes('::') && missing < 1) || (!normalized.includes('::') && missing !== 0)) {
    return null;
  }
  const groups = [
    ...left,
    ...Array.from({ length: Math.max(0, missing) }, () => '0'),
    ...right,
  ].map((part) => Number.parseInt(part, 16));
  if (groups.length !== 8) return null;

  return groups.flatMap((group) => [group >> 8, group & 0xff]);
}

function hasPrefix(bytes: number[], prefix: number[]) {
  return prefix.every((value, index) => bytes[index] === value);
}

function isPublicIpv6(value: string) {
  const bytes = parseIpv6(value);
  if (!bytes) return false;

  // Public IPv6 unicast is currently allocated from 2000::/3. Keeping the
  // allowlist narrow also rejects loopback, link-local, ULA and multicast.
  if ((bytes[0] & 0xe0) !== 0x20) return false;
  if (hasPrefix(bytes, [0x20, 0x01, 0x0d, 0xb8])) return false; // documentation
  if (hasPrefix(bytes, [0x20, 0x01, 0x00, 0x00])) return false; // Teredo
  if (hasPrefix(bytes, [0x20, 0x02])) return false; // 6to4 / embedded IPv4
  if (bytes[0] === 0x20 && bytes[1] === 0x01 && (bytes[2] & 0xf0) === 0x20) return false; // ORCHID
  return true;
}

export function isPublicIpAddress(value: string) {
  const normalized = normalizeHostname(value);
  if (parseIpv4(normalized)) return isPublicIpv4(normalized);
  if (parseIpv6(normalized)) return isPublicIpv6(normalized);
  return false;
}

function parseSafeUrl(urlValue: string): URL {
  const url = new URL(urlValue);
  if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password) {
    throw new Error('URL inválida ou não permitida');
  }
  if (
    (url.protocol === 'http:' && url.port && url.port !== '80')
    || (url.protocol === 'https:' && url.port && url.port !== '443')
  ) {
    throw new Error('Porta de destino não permitida');
  }

  const hostname = normalizeHostname(url.hostname);
  if (
    !hostname
    || hostname === 'localhost'
    || (!hostname.includes('.') && !parseIpv6(hostname))
    || BLOCKED_HOST_SUFFIXES.some((suffix) => hostname.endsWith(suffix))
  ) {
    throw new Error('Host de destino não permitido');
  }
  if ((parseIpv4(hostname) || parseIpv6(hostname)) && !isPublicIpAddress(hostname)) {
    throw new Error('Endereço de rede privado ou reservado');
  }
  return url;
}

// Compatibilidade para validações sintáticas. A autorização de uma requisição
// de rede deve sempre usar assertUrlResolvesPublic, que também consulta DNS.
export function isUrlSafe(urlValue: string): boolean {
  try {
    parseSafeUrl(urlValue);
    return true;
  } catch {
    return false;
  }
}

const denoResolver: DnsResolver = (hostname, recordType) =>
  Deno.resolveDns(hostname, recordType) as Promise<string[]>;

export async function assertUrlResolvesPublic(
  urlValue: string,
  resolver: DnsResolver = denoResolver,
): Promise<URL> {
  const url = parseSafeUrl(urlValue);
  const hostname = normalizeHostname(url.hostname);
  if (parseIpv4(hostname) || parseIpv6(hostname)) return url;

  const lookups = await Promise.allSettled([
    resolver(hostname, 'A'),
    resolver(hostname, 'AAAA'),
  ]);
  const addresses = lookups.flatMap((result) => result.status === 'fulfilled' ? result.value : []);
  if (addresses.length === 0 || addresses.length > 32) {
    throw new Error('Não foi possível resolver o host de destino');
  }
  if (addresses.some((address) => !isPublicIpAddress(address))) {
    throw new Error('O host resolve para uma rede privada ou reservada');
  }
  return url;
}

﻿/**
 * r2.ts — Módulo compartilhado para acesso ao Cloudflare R2 via API S3
 * Usado pelas Edge Functions do Supabase para upload/download/delete de arquivos.
 *
 * Requer as variáveis de ambiente (Supabase Secrets):
 *   R2_ACCOUNT_ID   — ID da conta Cloudflare
 *   R2_ACCESS_KEY_ID — Access Key ID do R2 API Token
 *   R2_SECRET_ACCESS_KEY — Secret Access Key do R2 API Token
 *   R2_BUCKET_NAME  — Nome do bucket (gsa-hub-storage)
 *   R2_PUBLIC_URL   — URL pública do bucket R2
 */

export const R2_BUCKET = Deno.env.get('R2_BUCKET_NAME') ?? 'gsa-hub-storage';
export const R2_PUBLIC_URL = Deno.env.get('R2_PUBLIC_URL') ?? 'https://pub-7f7b1419c83c407ba9bcf6512329e79a.r2.dev';

const R2_ACCOUNT_ID = () => Deno.env.get('R2_ACCOUNT_ID') ?? '';
const R2_ACCESS_KEY = () => Deno.env.get('R2_ACCESS_KEY_ID') ?? '';
const R2_SECRET_KEY = () => Deno.env.get('R2_SECRET_ACCESS_KEY') ?? '';

function getEndpoint() {
  return `https://${R2_ACCOUNT_ID()}.r2.cloudflarestorage.com`;
}

// ─── AWS Signature V4 ─────────────────────────────────────────────────────────
async function hmac(key: ArrayBuffer | Uint8Array, data: string): Promise<ArrayBuffer> {
  const k = await crypto.subtle.importKey('raw', key, { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  return crypto.subtle.sign('HMAC', k, new TextEncoder().encode(data));
}

async function sha256hex(data: string | Uint8Array): Promise<string> {
  const buf = typeof data === 'string' ? new TextEncoder().encode(data) : data;
  const hash = await crypto.subtle.digest('SHA-256', buf);
  return Array.from(new Uint8Array(hash)).map(b => b.toString(16).padStart(2, '0')).join('');
}

async function signRequest(
  method: string,
  key: string,
  body: Uint8Array | null,
  contentType?: string,
): Promise<Record<string, string>> {
  const endpoint = getEndpoint();
  const region = 'auto';
  const service = 's3';
  const now = new Date();
  const date = now.toISOString().slice(0, 10).replace(/-/g, '');
  const datetime = now.toISOString().replace(/[-:]/g, '').slice(0, 15) + 'Z';
  const host = new URL(endpoint).host;

  const payloadHash = body ? await sha256hex(body) : 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855';
  const signedHeaders = contentType
    ? 'content-type;host;x-amz-content-sha256;x-amz-date'
    : 'host;x-amz-content-sha256;x-amz-date';

  const canonicalHeaders = contentType
    ? `content-type:${contentType}\nhost:${host}\nx-amz-content-sha256:${payloadHash}\nx-amz-date:${datetime}\n`
    : `host:${host}\nx-amz-content-sha256:${payloadHash}\nx-amz-date:${datetime}\n`;

  const canonicalPath = `/${R2_BUCKET}/${key.replace(/^\/+/, '')}`;
  const canonicalRequest = [method, canonicalPath, '', canonicalHeaders, signedHeaders, payloadHash].join('\n');

  const credentialScope = `${date}/${region}/${service}/aws4_request`;
  const stringToSign = ['AWS4-HMAC-SHA256', datetime, credentialScope, await sha256hex(canonicalRequest)].join('\n');

  const enc = new TextEncoder();
  const kDate = await hmac(enc.encode(`AWS4${R2_SECRET_KEY()}`), date);
  const kRegion = await hmac(kDate, region);
  const kService = await hmac(kRegion, service);
  const kSigning = await hmac(kService, 'aws4_request');
  const signatureBytes = await hmac(kSigning, stringToSign);
  const signature = Array.from(new Uint8Array(signatureBytes)).map(b => b.toString(16).padStart(2, '0')).join('');

  const authHeader = `AWS4-HMAC-SHA256 Credential=${R2_ACCESS_KEY()}/${credentialScope}, SignedHeaders=${signedHeaders}, Signature=${signature}`;

  return {
    Authorization: authHeader,
    'x-amz-date': datetime,
    'x-amz-content-sha256': payloadHash,
    ...(contentType ? { 'Content-Type': contentType } : {}),
  };
}

// ─── Upload de arquivo ────────────────────────────────────────────────────────
export async function r2Upload(
  key: string,
  body: Uint8Array,
  contentType: string,
): Promise<{ publicUrl: string; path: string }> {
  const normalizedKey = key.replace(/^\/+/, '');
  const headers = await signRequest('PUT', normalizedKey, body, contentType);

  const resp = await fetch(`${getEndpoint()}/${R2_BUCKET}/${normalizedKey}`, {
    method: 'PUT',
    headers,
    body,
  });

  if (!resp.ok) {
    const text = await resp.text();
    throw new Error(`R2 upload falhou [${resp.status}]: ${text}`);
  }

  return {
    publicUrl: `${R2_PUBLIC_URL}/${normalizedKey}`,
    path: normalizedKey,
  };
}

// ─── Download de arquivo ──────────────────────────────────────────────────────
export async function r2Download(key: string): Promise<{ body: Uint8Array; contentType: string }> {
  const normalizedKey = key.replace(/^\/+/, '');
  const headers = await signRequest('GET', normalizedKey, null);

  const resp = await fetch(`${getEndpoint()}/${R2_BUCKET}/${normalizedKey}`, { headers });
  if (!resp.ok) throw new Error(`R2 download falhou [${resp.status}]`);

  const body = new Uint8Array(await resp.arrayBuffer());
  const contentType = resp.headers.get('content-type') ?? 'application/octet-stream';
  return { body, contentType };
}

// ─── Delete de arquivo(s) ────────────────────────────────────────────────────
export async function r2Delete(keys: string[]): Promise<void> {
  await Promise.all(
    keys.map(async (key) => {
      const normalizedKey = key.replace(/^\/+/, '');
      const headers = await signRequest('DELETE', normalizedKey, null);
      const resp = await fetch(`${getEndpoint()}/${R2_BUCKET}/${normalizedKey}`, { method: 'DELETE', headers });
      if (!resp.ok && resp.status !== 404) {
        throw new Error(`R2 delete falhou [${resp.status}]: ${key}`);
      }
    }),
  );
}

// ─── URL pública ──────────────────────────────────────────────────────────────
export function r2PublicUrl(key: string): string {
  return `${R2_PUBLIC_URL}/${key.replace(/^\/+/, '')}`;
}

